import java.sql.*; public class _Q2 { public static void main(String[] a) throws Exception { Connection c = DriverManager.getConnection("jdbc:sqlserver://127.0.0.1:1433;databaseName=HSDZ_MES;encrypt=false", "yinjia", "Yinjia@2026"); Statement s = c.createStatement(); ResultSet r = s.executeQuery("SELECT panel_code, panel_name, prefix FROM yj_panel WHERE panel_code IN ('QC_RECV','QC_INSP','QC_RETURN')"); while (r.next()) System.out.println(r.getString(1) + " | " + r.getString(2) + " | " + r.getString(3)); r = s.executeQuery("SELECT panel_code, COUNT(*) FROM yj_field WHERE panel_code IN ('QC_RECV','QC_INSP','QC_RETURN') GROUP BY panel_code"); while (r.next()) System.out.println("fields: " + r.getString(1) + " = " + r.getInt(2)); c.close(); } }